import"chrome://resources/cr_elements/cr_button/cr_button.js";import"chrome://resources/polymer/v3_0/iron-icon/iron-icon.js";import"chrome://resources/polymer/v3_0/paper-spinner/paper-spinner-lite.js";import"chrome://resources/polymer/v3_0/paper-styles/color.js";import"chrome://resources/cr_elements/icons.html.js";import"chrome://resources/cr_components/localized_link/localized_link.js";import"./icons.html.js";import"./strings.m.js";import"./signin_shared.css.js";import"./signin_vars.css.js";import"./tangible_sync_style_shared.css.js";import{I18nMixin}from"chrome://resources/cr_elements/i18n_mixin.js";import{WebUiListenerMixin}from"chrome://resources/cr_elements/web_ui_listener_mixin.js";import{assert,assertNotReached}from"chrome://resources/js/assert.js";import{loadTimeData}from"chrome://resources/js/load_time_data.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getTemplate}from"./sync_confirmation_app.html.js";import{SyncConfirmationBrowserProxyImpl}from"./sync_confirmation_browser_proxy.js";const SyncConfirmationAppElementBase=WebUiListenerMixin(I18nMixin(PolymerElement));export class SyncConfirmationAppElement extends SyncConfirmationAppElementBase{constructor(){super(...arguments);this.syncConfirmationBrowserProxy_=SyncConfirmationBrowserProxyImpl.getInstance()}static get is(){return"sync-confirmation-app"}static get template(){return getTemplate()}static get properties(){return{accountImageSrc_:{type:String,value(){return loadTimeData.getString("accountPictureUrl")}},anyButtonClicked_:{type:Boolean,value:false},isModalDialog_:{type:Boolean,value(){return loadTimeData.getBoolean("isModalDialog")}},showEnterpriseBadge_:{type:Boolean,value:false},syncBenefitsList_:{type:Array,value(){return JSON.parse(loadTimeData.getString("syncBenefitsList"))}},useClickableSyncInfoDesc_:{type:Boolean,value(){return loadTimeData.getBoolean("useClickableSyncInfoDesc")}}}}connectedCallback(){super.connectedCallback();this.addWebUiListener("account-info-changed",this.handleAccountInfoChanged_.bind(this));this.syncConfirmationBrowserProxy_.requestAccountInfo()}onConfirm_(e){this.anyButtonClicked_=true;this.syncConfirmationBrowserProxy_.confirm(this.getConsentDescription_(),this.getConsentConfirmation_(e.composedPath()))}onUndo_(){this.anyButtonClicked_=true;this.syncConfirmationBrowserProxy_.undo()}onGoToSettings_(e){this.anyButtonClicked_=true;this.syncConfirmationBrowserProxy_.goToSettings(this.getConsentDescription_(),this.getConsentConfirmation_(e.composedPath()))}getConsentConfirmation_(path){for(const element of path){if(element.nodeType!==Node.DOCUMENT_FRAGMENT_NODE&&element.hasAttribute("consent-confirmation")){return element.innerHTML.trim()}}assertNotReached("No consent confirmation element found.")}getConsentDescription_(){const consentDescription=Array.from(this.shadowRoot.querySelectorAll("[consent-description]")).filter((element=>element.getBoundingClientRect().width*element.getBoundingClientRect().height>0)).map((element=>element.hasAttribute("localized-string")?element.getAttribute("localized-string"):element.innerHTML.trim()));assert(consentDescription.length);return consentDescription}handleAccountInfoChanged_(accountInfo){this.accountImageSrc_=accountInfo.src;this.showEnterpriseBadge_=accountInfo.showEnterpriseBadge}onDisclaimerClicked_(event){event.detail.event.preventDefault();this.syncConfirmationBrowserProxy_.openDeviceSyncSettings()}getAnimationClass_(){return!this.isModalDialog_?"fade-in":""}getMaybeDialogClass_(){return this.isModalDialog_?"dialog":""}}customElements.define(SyncConfirmationAppElement.is,SyncConfirmationAppElement);